/// The plan review's round files beside `subject`: `<stem>.feedback-<n>.md`.
/// Mirrors Switchboard's `core::workflow::round_paths`, which names the
/// files the review writes (Dispatch does not link the app): a rename
/// there is carried over here.
#[must_use]
pub fn round_file(subject: &Path, n: u32) -> PathBuf {
    beside(subject, "feedback", n)
}

/// The plan review round numbers whose feedback file is beside
/// `subject`, ascending. Listed rather than counted up from 1: a round
/// sent from the app's notes box writes no file, and every round after
/// it still has one.
#[must_use]
pub fn plan_round_numbers(subject: &Path) -> Vec<u32> {
    let dir = subject.parent().unwrap_or_else(|| Path::new("/"));
    let Ok(entries) = std::fs::read_dir(dir) else {
        return Vec::new();
    };
    let names: Vec<String> = entries
        .filter_map(|e| e.ok()?.file_name().into_string().ok())
        .collect();
    round_numbers(subject, names.iter().map(String::as_str))
}

/// The `n`s of the names `<stem>.feedback-<n>.md` among `names`, the
/// file names in `subject`'s directory, ascending.
#[must_use]
pub fn round_numbers<'a>(subject: &Path, names: impl IntoIterator<Item = &'a str>) -> Vec<u32> {
    let stem = subject
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default();
    let prefix = format!("{stem}.feedback-");
    let mut ns: Vec<u32> = names
        .into_iter()
        .filter_map(|name| {
            name.strip_prefix(&prefix)?
                .strip_suffix(".md")?
                .parse()
                .ok()
        })
        .collect();
    ns.sort_unstable();
    ns.dedup();
    ns
}

/// The response to plan review round `n` beside `subject`:
/// `<stem>.response-<n>.md`, mirrored as `round_file` is.
#[must_use]
pub fn response_file(subject: &Path, n: u32) -> PathBuf {
    beside(subject, "response", n)
}

/// `<stem>.<suffix>-<n>.md` beside `subject`: one place for the shape
/// both round names share.
fn beside(subject: &Path, suffix: &str, n: u32) -> PathBuf {
    let stem = subject
        .file_stem()
        .map(|s| s.to_string_lossy().into_owned())
        .unwrap_or_default();
    subject.with_file_name(format!("{stem}.{suffix}-{n}.md"))
}

